css:
.insurance-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #d6deeb;
}

.insurance-sim-header {
    border-left: 4px solid #00bfff;
    padding: 22px 28px;
    margin-bottom: 22px;
    background: linear-gradient(90deg, rgba(0,191,255,0.10) 0%, rgba(0,191,255,0.0) 100%);
}
.insurance-sim-brand {
    color: #6b85a8;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    margin-bottom: 8px;
    font-weight: 600;
}
.insurance-sim-header h1 {
    color: #ffffff;
    font-size: 1.55rem;
    margin: 0 0 6px 0;
    font-weight: 600;
    letter-spacing: 0.01em;
}
.insurance-sim-subtitle {
    color: #7a92b3;
    font-size: 0.92rem;
    font-style: italic;
}

.insurance-sim-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #111827;
    border: 1px solid #1f2d3d;
    padding: 14px 22px;
    border-radius: 6px;
    margin-bottom: 22px;
}
.insurance-sim-period {
    color: #d6deeb;
    font-size: 0.95rem;
}
.insurance-sim-period span {
    margin: 0 4px;
}
.insurance-sim-period span#currentDay,
.insurance-sim-period span#maxPeriods {
    color: #00bfff;
    font-weight: 700;
}
.insurance-sim-round-badge {
    background: #00bfff;
    color: #0a0f1e;
    padding: 6px 14px;
    border-radius: 4px;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    box-shadow: 0 0 14px rgba(0,191,255,0.35);
}

.insurance-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}
.insurance-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 18px 16px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.insurance-sim-kpi-card:hover {
    border-color: #2d4566;
    transform: translateY(-2px);
}
.insurance-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00bfff, #00ff88);
}
.insurance-sim-kpi-critical::before {
    background: linear-gradient(90deg, #ff6b35, #ffb347);
}
.insurance-sim-kpi-label {
    color: #6b85a8;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 600;
}
.insurance-sim-kpi-value {
    font-size: 1.55rem;
    font-weight: 700;
    color: #ffffff;
    line-height: 1.2;
}
.insurance-sim-kpi-critical .insurance-sim-kpi-value {
    color: #ff8b50;
}

.insurance-sim-briefing {
    background: #0f1827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00ff88;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.insurance-sim-briefing-title {
    color: #00ff88;
    font-size: 1.05rem;
    font-weight: 700;
    margin-bottom: 12px;
    letter-spacing: 0.02em;
}
.insurance-sim-briefing-text {
    color: #c0cce0;
    font-size: 0.94rem;
    line-height: 1.6;
}
.insurance-sim-briefing-text b {
    color: #ffffff;
}

.insurance-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 24px;
    margin-bottom: 24px;
}
.insurance-sim-controls h3 {
    color: #ffffff;
    font-size: 1.0rem;
    margin: 0 0 18px 0;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    border-bottom: 1px solid #1f2d3d;
    padding-bottom: 12px;
}
.insurance-sim-control-panel h4 {
    color: #00bfff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 16px 0;
    font-weight: 700;
}
.insurance-sim-control-panel label {
    display: block;
    color: #b3c2d8;
    font-size: 0.88rem;
    margin-bottom: 8px;
}
.insurance-sim-control-panel input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #ffffff;
    border-radius: 4px;
    padding: 10px 14px;
    width: 100%;
    max-width: 280px;
    font-size: 1rem;
    margin-bottom: 12px;
}
.insurance-sim-control-panel input[type="number"]:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 0 3px rgba(0,191,255,0.18);
}
.insurance-sim-control-panel select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #ffffff;
    border-radius: 4px;
    padding: 10px 14px;
    width: 100%;
    max-width: 280px;
}
.insurance-sim-control-panel select option {
    background: #111827;
    color: #ffffff;
}
.insurance-sim-lever {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
    padding: 12px 14px;
    background: #0a0f1e;
    border: 1px solid #1f2d3d;
    border-radius: 4px;
    margin-bottom: 10px;
    transition: border-color 0.2s ease;
}
.insurance-sim-lever:hover {
    border-color: #2d4566;
}
.insurance-sim-lever input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #00bfff;
    cursor: pointer;
    flex-shrink: 0;
}
.insurance-sim-lever label {
    color: #d6deeb;
    margin: 0;
    flex: 1;
    cursor: pointer;
    font-size: 0.92rem;
}
.insurance-sim-lever-numeric {
    align-items: center;
}
.insurance-sim-lever-numeric label {
    flex: 1 1 auto;
    min-width: 200px;
}
.insurance-sim-lever input[type="number"] {
    max-width: 110px;
    margin: 0;
    background: #111827;
    border: 1px solid #2d3f55;
    color: #ffffff;
    border-radius: 4px;
    padding: 8px 10px;
}

.insurance-sim-actions {
    margin-top: 18px;
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    border-top: 1px solid #1f2d3d;
    padding-top: 18px;
}
.insurance-sim-actions .btn-primary {
    background: #00bfff;
    border: none;
    color: #0a0f1e;
    font-weight: 700;
    padding: 11px 28px;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 0.85rem;
    transition: background 0.2s ease, box-shadow 0.2s ease;
}
.insurance-sim-actions .btn-primary:hover {
    background: #33ccff;
    box-shadow: 0 0 18px rgba(0,191,255,0.4);
}
.insurance-sim-actions .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #7a92b3;
    padding: 8px 18px;
    border-radius: 4px;
    font-size: 0.82rem;
}
.insurance-sim-actions .btn-outline-secondary:hover {
    border-color: #6b85a8;
    color: #d6deeb;
    background: #0a0f1e;
}

.insurance-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(380px, 1fr));
    gap: 18px;
    margin-bottom: 22px;
}
.insurance-sim-chart-wrap {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 18px;
    height: 320px;
    position: relative;
}

.insurance-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 18px;
    overflow-x: auto;
}
.insurance-sim-history table {
    color: #d6deeb;
    width: 100%;
    margin: 0;
    background: transparent;
}
.insurance-sim-history thead th {
    color: #6b85a8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #2d3f55;
    border-top: none;
    padding: 10px 12px;
    text-align: left;
    background: transparent;
}
.insurance-sim-history tbody td {
    border-bottom: 1px solid #1f2d3d;
    border-top: none;
    padding: 10px 12px;
    font-size: 0.9rem;
    color: #c0cce0;
    background: transparent;
}
.insurance-sim-history tbody tr:hover td {
    background: rgba(0,191,255,0.04);
}

@media (max-width: 768px) {
    .insurance-sim-container {
        padding: 16px;
    }
    .insurance-sim-header {
        padding: 16px 20px;
    }
    .insurance-sim-header h1 {
        font-size: 1.25rem;
    }
    .insurance-sim-meta {
        flex-direction: column;
        gap: 10px;
        align-items: flex-start;
    }
    .insurance-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .insurance-sim-kpi-value {
        font-size: 1.25rem;
    }
    .insurance-sim-charts {
        grid-template-columns: 1fr;
    }
    .insurance-sim-chart-wrap {
        height: 260px;
    }
    .insurance-sim-controls {
        padding: 18px;
    }
}


/* ---- EQIL 2026-08-07: accessibility + end-of-run debrief (dark theme, matches #0a0f1e / #111827) ---- */
.insurance-sim-container :focus-visible,
.insurance-sim-container button:focus-visible,
.insurance-sim-container input:focus-visible,
.insurance-sim-container select:focus-visible {
    outline: 3px solid #00bfff;
    outline-offset: 2px;
    border-radius: 4px;
}

@media (prefers-reduced-motion: reduce) {
    .insurance-sim-container *,
    .insurance-sim-container *::before,
    .insurance-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

.insurance-sim-completion { margin: 20px 0 8px; }

.insurance-sim-debrief {
    background: #111827;
    border: 1px solid #1e2b45;
    border-left: 5px solid #00bfff;
    border-radius: 8px;
    padding: 24px 28px;
    color: #d6deeb;
}

.insurance-sim-debrief h3 { margin: 0 0 14px; font-size: 1.2rem; color: #ffffff; }
.insurance-sim-debrief h4 {
    margin: 22px 0 10px;
    font-size: 0.78rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #9fb2cd;
}

.insurance-sim-debrief-score {
    display: flex;
    align-items: baseline;
    gap: 8px;
    flex-wrap: wrap;
    margin-bottom: 18px;
}

.insurance-sim-debrief-num { font-size: 2.7rem; font-weight: 700; line-height: 1; color: #00bfff; }
.insurance-sim-debrief-den { font-size: 1.1rem; color: #9fb2cd; }

.insurance-sim-debrief-band {
    margin-left: 10px;
    padding: 4px 14px;
    border: 1px solid #00bfff;
    border-radius: 999px;
    font-size: 0.85rem;
    font-weight: 600;
    color: #ffffff;
}

.insurance-sim-debrief-stats,
.insurance-sim-debrief-levers {
    list-style: none;
    margin: 0 0 12px;
    padding: 0;
    display: grid;
    gap: 10px;
}

.insurance-sim-debrief-stats { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
.insurance-sim-debrief-levers { grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); }

.insurance-sim-debrief-stats li,
.insurance-sim-debrief-levers li {
    background: #0f1827;
    border: 1px solid #1e2b45;
    border-radius: 6px;
    padding: 10px 14px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
}

.insurance-sim-debrief-stats li span { color: #9fb2cd; font-size: 0.8rem; }
.insurance-sim-debrief-stats li strong { color: #ffffff; font-size: 1rem; text-align: right; }

.insurance-sim-debrief-levers li { display: block; font-size: 0.86rem; border-left: 4px solid #33405c; }
.insurance-sim-debrief-levers li.is-on { border-left-color: #00ff88; color: #ffffff; }
.insurance-sim-debrief-levers li.is-off { border-left-color: #33405c; color: #9fb2cd; }

.insurance-sim-debrief-insights { margin: 0; padding-left: 20px; line-height: 1.6; color: #d6deeb; }
.insurance-sim-debrief-insights li { margin-bottom: 8px; }

@media (max-width: 640px) {
    .insurance-sim-debrief { padding: 16px; }
    .insurance-sim-debrief-num { font-size: 2.1rem; }
}

