                return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
            };

            // Generate 1000 customers with lognormal expected annual healthcare costs.
            // Calibration: median EUR 1800, mean EUR 3200 (per concept 1305 spec).
            const mu = Math.log(1800);
            const sigma = Math.sqrt(2 * Math.log(3200 / 1800));
            this.population = [];
            for (let i = 0; i < 1000; i++) {
                const u1 = Math.max(rng(), 1e-9);
                const u2 = rng();
                const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
                const c = Math.exp(mu + sigma * z);
                this.population.push(Math.round(c));
            }
            this.populationSum = this.population.reduce(function(a, b) { return a + b; }, 0);
            this.populationMean = this.populationSum / this.population.length;
        }

        getRound(period) {
            // 9 periods, three phases of three.
            const p = period || 1;
            if (p <= 3) return 1;
            if (p <= 6) return 2;
            return 3;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cumulativeProfit: 0,
                    lossRatioHistory: [],
                    enrollmentHistory: [],
                    roundLabels: [],
                    perCapitaSpendHistory: [],
                    coverageRateHistory: [],
                    lastPremium: 3200,
                    scoreR2Coinsurance: null,
                    scoreR3: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    premium: 3200,
                    coinsurance: null,
                    mandate: false,
                    riskRated: false,
                    managedCare: false,
                    cs_round3: null
                };
            }
            const self = this;
            setTimeout(function() {
                self._updateBriefing(state);
                self._syncControlsFromDecisions(state);
            }, 80);
        }

        validateDecisions(decisions) {
            const period = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.currentPeriod) || 1;
            const round = this.getRound(period);
            this._updateBriefing({ currentPeriod: period });

            if (round === 1) {
                const el = document.getElementById('premiumInput');
                if (el) decisions.premium = parseFloat(el.value);
                if (!decisions.premium || decisions.premium < 500 || decisions.premium > 50000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('premium_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 2) {
                const el = document.getElementById('coinsuranceInput');
                if (el && String(el.value).trim() === '') {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('coinsurance_blank'), 'warning'
                    );
                    return false;
                }
                if (el) decisions.coinsurance = parseFloat(el.value);
                if (isNaN(decisions.coinsurance) || decisions.coinsurance < 0 || decisions.coinsurance > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('coinsurance_warning'), 'warning'
                    );
                    return false;
                }
            } else {
                const m1 = document.getElementById('leverMandate');
                const m2 = document.getElementById('leverRiskRated');
                const m4 = document.getElementById('leverManagedCare');
                const cs = document.getElementById('costShareInput');
                if (m1) decisions.mandate = m1.checked;
                if (m2) decisions.riskRated = m2.checked;
                if (m4) decisions.managedCare = m4.checked;
                if (cs && String(cs.value).trim() === '') {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('coinsurance_blank'), 'warning'
                    );
                    return false;
                }
                if (cs) decisions.cs_round3 = parseFloat(cs.value);
                if (isNaN(decisions.cs_round3) || decisions.cs_round3 < 0 || decisions.cs_round3 > 80) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('coinsurance_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const round = this.getRound(state.currentPeriod);
            const d = state.decisions;
            let result;

            if (round === 1) {
                result = this._calcRound1(d);
                state.domainState.lastPremium = d.premium;
            } else if (round === 2) {
                result = this._calcRound2(d, state);
            } else {
                result = this._calcRound3(d);
            }

            result.period = state.currentPeriod;
            result.round = round;

            state.domainState.lossRatioHistory.push(Math.round(result.lossRatio * 100));
            state.domainState.enrollmentHistory.push(result.enrolled);
            state.domainState.roundLabels.push('R' + round + '·P' + state.currentPeriod);
            state.domainState.perCapitaSpendHistory.push(Math.round(result.perCapitaSpend || 0));
            state.domainState.coverageRateHistory.push(Math.round((result.enrolled / 1000) * 100));
            state.domainState.cumulativeProfit += (result.netResult || 0);

            if (round === 2) state.domainState.scoreR2Coinsurance = result.coinsurance;
            if (round === 3) {
                state.domainState.scoreR3 = {
                    coinsurance: result.coinsurance, mandate: !!result.mandate, riskRated: !!result.riskRated,
                    managedCare: !!result.managedCare, healthProxy: result.healthProxy || 0, lossRatio: result.lossRatio
                };
            }
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: this._runningScore(state.domainState) });

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return result;
        }

        _calcRound1(d) {
            // Adverse-selection logic: each individual buys if their privately-known c_i,
            // adjusted upward for variance-reduction value (small risk premium), exceeds the posted premium.
            // Approximation: person enrolls if c_i >= premium * 0.88.
            const premium = d.premium;
            const threshold = premium * 0.88;
            const enrolled = this.population.filter(function(c) { return c >= threshold; });
            const enrolledCount = enrolled.length;
            const sumClaims = enrolled.reduce(function(a, b) { return a + b; }, 0);
            const conditionalMean = enrolledCount > 0 ? sumClaims / enrolledCount : 0;
            const adminLoading = enrolledCount * 280;
            const totalPremium = enrolledCount * premium;
            const lossRatio = totalPremium > 0 ? sumClaims / totalPremium : 0;
            const netResult = totalPremium - sumClaims - adminLoading;

            return {
                enrolled: enrolledCount,
                premium: Math.round(premium),
                conditionalMean: Math.round(conditionalMean),
                totalPremium: Math.round(totalPremium),
                totalClaims: Math.round(sumClaims),
                lossRatio: lossRatio,
                netResult: Math.round(netResult),
                copay: 0,
                perCapitaSpend: Math.round(conditionalMean),
                coverage: enrolledCount / 10
            };
        }

        _calcRound2(d, state) {
            // Moral-hazard: hold premium at last Round-1 level. Vary coinsurance.
            // Utilization multiplier on c_i: 1 + 0.625*(1 - coinsurance) — calibrated so
            // full-coverage gives +62.5% utilisation (RAND HIE: ~+45–60%, lab uses 60%).
            const premium = state.domainState.lastPremium || 3200;
            const cins = d.coinsurance / 100;
            const threshold = premium * 0.88;
            const enrolled = this.population.filter(function(c) { return c >= threshold; });
            const enrolledCount = enrolled.length;
            const baseClaims = enrolled.reduce(function(a, b) { return a + b; }, 0);
            const utilizationMult = 1 + 0.625 * (1 - cins);
            const grossClaims = baseClaims * utilizationMult;
            const insurerPays = grossClaims * (1 - cins);
            const consumerPays = grossClaims * cins;
            const adminLoading = enrolledCount * 280;
            const totalPremium = enrolledCount * premium;
            const lossRatio = totalPremium > 0 ? insurerPays / totalPremium : 0;
            const moralHazardWedge = enrolledCount > 0
                ? ((utilizationMult - 1) * baseClaims) / enrolledCount : 0;
            const netResult = totalPremium - insurerPays - adminLoading;

            return {
                enrolled: enrolledCount,
                premium: Math.round(premium),
                coinsurance: d.coinsurance,
                grossClaims: Math.round(grossClaims),
                insurerPays: Math.round(insurerPays),
                consumerPays: Math.round(consumerPays),
                lossRatio: lossRatio,
                netResult: Math.round(netResult),
                moralHazardWedge: Math.round(moralHazardWedge),
                copay: d.coinsurance,
                conditionalMean: enrolledCount > 0 ? Math.round(baseClaims / enrolledCount) : 0,
                perCapitaSpend: enrolledCount > 0 ? Math.round(grossClaims / enrolledCount) : 0,
                coverage: enrolledCount / 10
            };
        }

        _calcRound3(d) {
            // Institutional design under four mechanism levers.
            const cs = (d.cs_round3 || 0) / 100;
            let enrolledArr;
            let premium;
            let totalPremium;

            if (d.mandate) {
                // M1 — everyone enrolls
                enrolledArr = this.population.slice();
                if (d.riskRated) {
                    // M2 — perfect risk-rating with 10% loading per individual
                    totalPremium = this.populationSum * 1.10;
                    premium = this.populationMean * 1.10;
                } else {
                    // Community rating at population mean + loading
                    premium = this.populationMean * 1.10;
                    totalPremium = enrolledArr.length * premium;
                }
            } else {
                if (d.riskRated) {
                    // M2 alone — risk-rated premiums approximate separating equilibrium;
                    // most consumers enroll because their premium tracks their expected cost
                    enrolledArr = this.population.slice();
                    totalPremium = this.populationSum * 1.10;
                    premium = this.populationMean * 1.10;
                } else {
                    // No mandate, no risk-rating: community-rated premium at the population mean,
                    // adverse-selection self-selection bites
                    premium = this.populationMean * 1.10;
                    const threshold = premium * 0.88;
                    enrolledArr = this.population.filter(function(c) { return c >= threshold; });
                    totalPremium = enrolledArr.length * premium;
                }
            }

            const enrolledCount = enrolledArr.length;
            const sumExpected = enrolledArr.reduce(function(a, b) { return a + b; }, 0);

            // Moral hazard utilisation
            let utilizationMult = 1 + 0.625 * (1 - cs);
            // M4 — managed care reduces utilisation a further 15%
            if (d.managedCare) utilizationMult *= 0.85;

            const grossClaims = sumExpected * utilizationMult;
            const insurerPays = grossClaims * (1 - cs);

            // Administrative cost share
            let adminPct = 0.08;
            if (d.riskRated) adminPct += 0.03;
            if (d.managedCare) adminPct += 0.07;
            const adminCost = totalPremium * adminPct;

            const lossRatio = totalPremium > 0 ? insurerPays / totalPremium : 0;
            const netResult = totalPremium - insurerPays - adminCost;
            const perCapitaSpend = enrolledCount > 0 ? grossClaims / enrolledCount : 0;
            const coverageRate = enrolledCount / 10;

            // Health proxy 0–100: rewards coverage breadth and full-value access for low-income;
            // penalises high cost-share (RAND finding) and managed-care friction
            let healthProxy = 45 + (enrolledCount / 1000) * 35 - cs * 18;
            if (d.managedCare) healthProxy -= 5;
            if (d.mandate) healthProxy += 5;
            healthProxy = Math.max(0, Math.min(100, Math.round(healthProxy)));

            return {
                enrolled: enrolledCount,
                premium: Math.round(premium),
                mandate: d.mandate,
                riskRated: d.riskRated,
                managedCare: d.managedCare,
                coinsurance: d.cs_round3,
                grossClaims: Math.round(grossClaims),
                insurerPays: Math.round(insurerPays),
                lossRatio: lossRatio,
                netResult: Math.round(netResult),
                copay: d.cs_round3,
                conditionalMean: enrolledCount > 0 ? Math.round(sumExpected / enrolledCount) : 0,
                perCapitaSpend: Math.round(perCapitaSpend),
                coverage: coverageRate,
                healthProxy: healthProxy,
                adminPct: Math.round(adminPct * 100)
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('enrolledDisplay', 'results.enrolled', function(v) {
                return (v == null ? 0 : v) + ' / 1000';
            });
            uiManager.bind('premiumDisplay', 'results.premium', function(v) {
                return '€' + (v == null ? 0 : v).toLocaleString();
            });
            uiManager.bind('lossRatioDisplay', 'results.lossRatio', function(v) {
                return Math.round((v == null ? 0 : v) * 100) + '%';
            });
            uiManager.bind('coverageDisplay', 'results.coverage', function(v) {
                return (v == null ? 0 : v).toFixed(1) + '%';
            });
            uiManager.bind('netResultDisplay', 'results.netResult', function(v) {
                return '€' + Math.round(v == null ? 0 : v).toLocaleString();
            });
            uiManager.bind('cumulativeProfitDisplay', 'domainState.cumulativeProfit', function(v) {
                return '€' + Math.round(v == null ? 0 : v).toLocaleString();
            });
            uiManager.bind('perCapitaDisplay', 'results.perCapitaSpend', function(v) {
                return '€' + (v == null ? 0 : v).toLocaleString();
            });
            uiManager.bind('conditionalMeanDisplay', 'results.conditionalMean', function(v) {
                return '€' + (v == null ? 0 : v).toLocaleString();
            });
        }

        getChartConfig() {
