        getChartData(state) {
            const labels = state.domainState.roundLabels || [];
            const lr = state.domainState.lossRatioHistory || [];
            const target = lr.map(function() { return 86; });
            const t = this._t();
            return {
                lossRatioChart: {
                    labels: labels,
                    datasets: [
                        { label: t('chart_loss_ratio'), data: lr },
                        { label: t('chart_target'), data: target }
                    ]
                },
                enrollmentChart: {
                    labels: labels,
                    datasets: [{ label: t('chart_enrolled'), data: state.domainState.enrollmentHistory || [] }]
                }
            };
        }

        _t() {
            const sim = window.mySimulation;
            return (sim && sim.t) ? sim.t.bind(sim) : function(k) { return k; };
        }

        _peak(v, target, tolerance, points) {
            // Triangular credit around an interior optimum: full points at target, zero once the
            // player is a whole tolerance away. Used where the right answer is a calibrated middle
            // rather than a corner, which is the point of both Zeckhauser and a solvent loss ratio.
            const x = 1 - (Math.abs(v - target) / tolerance);
            return points * Math.max(0, Math.min(1, x));
        }

        _composite(m) {
            // Round 1 is exploratory by authored design - the briefing tells the player to chase
            // the loss ratio upward and watch the pool unravel - so it is deliberately not graded
            // on outcome. Rounds 2 and 3 have defensible optima and carry the score.
            const coinsurancePts = this._peak(m.coinsurance, 25, 35, 25);
            let designPts = 0;
            if (m.mandate) {
                designPts += 18;
                if (m.coinsurance >= 10 && m.coinsurance <= 40) designPts += 12;
            } else if (m.riskRated) {
                designPts += 8;
            }
            const healthPts = 25 * (Math.max(0, Math.min(100, m.healthProxy || 0)) / 100);
            const solvencyPts = this._peak(m.finalLossRatio, 0.88, 0.45, 20);

            let score = Math.round(coinsurancePts + designPts + healthPts + solvencyPts);
            // Failure-state cap: a scheme that cannot pay its claims is not a good design however
            // broad its coverage. The old bands could return Excellent on a run that lost 8.9M.
            if (m.finalLossRatio > 1.20) score = Math.min(score, 55);
            return Math.max(0, Math.min(100, score));
        }

        _runningScore(ds) {
            // Same 0-100 composite as getPerformanceSummary: round 1 periods are ungraded (0), round 2 periods earn only the coinsurance points, round 3 periods get the full composite of the latest round 3 play
            const r3 = ds.scoreR3;
            const r2c = (ds.scoreR2Coinsurance != null) ? ds.scoreR2Coinsurance : null;
            if (r3) {
                return this._composite({
                    coinsurance: (r3.coinsurance != null) ? r3.coinsurance : ((r2c != null) ? r2c : 0),
                    mandate: !!r3.mandate,
                    riskRated: !!r3.riskRated,
                    managedCare: !!r3.managedCare,
                    healthProxy: r3.healthProxy || 0,
                    finalLossRatio: (r3.lossRatio != null) ? r3.lossRatio : 1
                });
            }
            if (r2c != null) return Math.max(0, Math.min(100, Math.round(this._peak(r2c, 25, 35, 25))));
            return 0;
        }

        _band(score) {
            if (score >= 80) return 'excellent';
            if (score >= 62) return 'good';
            if (score >= 45) return 'fair';
            return 'needs_work';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const t = this._t();
            const totalProfit = history.reduce(function(s, h) {
                return s + ((h.results && h.results.netResult) || 0);
            }, 0);
            const r2 = history.filter(function(h) { return h.results && h.results.round === 2; });
            const r3 = history.filter(function(h) { return h.results && h.results.round === 3; });
            const lastR2 = r2.length ? r2[r2.length - 1].results : null;
            const lastR3 = r3.length ? r3[r3.length - 1].results : null;

            const insights = [];
            if (!lastR3) {
                return {
                    totalProfit: Math.round(totalProfit),
                    composite: 0, overallScore: 0, totalScore: 0, score: 0,
                    performance: 'needs_work',
                    performanceKey: 'needs_work',
                    performanceLabel: t('perf_needs_work'),
                    insights: [t('insight_incomplete')]
                };
            }

            const metrics = {
                coinsurance: (lastR3.coinsurance != null) ? lastR3.coinsurance
                           : ((lastR2 && lastR2.coinsurance != null) ? lastR2.coinsurance : 0),
                mandate: !!lastR3.mandate,
                riskRated: !!lastR3.riskRated,
                managedCare: !!lastR3.managedCare,
                healthProxy: lastR3.healthProxy || 0,
                finalLossRatio: (lastR3.lossRatio != null) ? lastR3.lossRatio : 1
            };
            const score = this._composite(metrics);
            const band = this._band(score);

            if (metrics.mandate && metrics.coinsurance >= 10 && metrics.coinsurance <= 40) {
                insights.push(t('insight_mandate_cs'));
            } else if (metrics.mandate) {
                insights.push(t('insight_mandate_only'));
            } else if (metrics.riskRated) {
                insights.push(t('insight_risk_rated'));
            } else {
                insights.push(t('insight_no_mandate'));
            }
            if (metrics.managedCare) insights.push(t('insight_managed_care'));
            if (metrics.coinsurance >= 50) insights.push(t('insight_heavy_cs'));
            if (metrics.coinsurance === 0 && metrics.mandate) insights.push(t('insight_zero_copay'));
            if (metrics.finalLossRatio > 1.20) insights.push(t('insight_insolvent'));
            else if (metrics.finalLossRatio < 0.70) insights.push(t('insight_overpriced'));

            return {
                totalProfit: Math.round(totalProfit),
                finalLossRatio: Math.round(metrics.finalLossRatio * 100),
                healthProxy: metrics.healthProxy,
                enrolled: lastR3.enrolled,
                coinsurance: metrics.coinsurance,
                mandate: metrics.mandate,
                riskRated: metrics.riskRated,
                managedCare: metrics.managedCare,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                performance: band,
                performanceKey: band,
                performanceLabel: t('perf_' + band),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = this._t();
            const s = summary || {};
            const esc = function(v) {
                return String(v == null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            let html = '<div class="insurance-sim-debrief">';
            html += '<h3>' + esc(t('done_title')) + '</h3>';
            html += '<div class="insurance-sim-debrief-score">';
            html += '<span class="insurance-sim-debrief-num">' + esc(s.overallScore != null ? s.overallScore : 0) + '</span>';
            html += '<span class="insurance-sim-debrief-den">/100</span>';
            html += '<span class="insurance-sim-debrief-band">' + esc(s.performanceLabel || '') + '</span>';
            html += '</div>';
            html += '<ul class="insurance-sim-debrief-stats">';
            html += '<li><span>' + esc(t('enrolled_label')) + '</span><strong>' + esc(s.enrolled || 0) + ' / 1000</strong></li>';
            html += '<li><span>' + esc(t('loss_ratio_label')) + '</span><strong>' + esc(s.finalLossRatio || 0) + '%</strong></li>';
            html += '<li><span>' + esc(t('done_health')) + '</span><strong>' + esc(s.healthProxy || 0) + '/100</strong></li>';
            html += '<li><span>' + esc(t('coinsurance_label_short')) + '</span><strong>' + esc(s.coinsurance || 0) + '%</strong></li>';
            html += '<li><span>' + esc(t('cumulative_label')) + '</span><strong>' + esc(Math.round((s.totalProfit || 0) / 1000)) + 'k</strong></li>';
            html += '</ul>';
            html += '<ul class="insurance-sim-debrief-levers">';
            const levers = [['M1', 'lever_mandate_short', s.mandate], ['M2', 'lever_risk_short', s.riskRated],
                            ['M4', 'lever_mc_short', s.managedCare]];
            for (let i = 0; i < levers.length; i++) {
                html += '<li class="' + (levers[i][2] ? 'is-on' : 'is-off') + '">' +
                        esc(levers[i][0]) + ' ' + esc(t(levers[i][1])) + ' — ' +
                        esc(levers[i][2] ? t('lever_on') : t('lever_off')) + '</li>';
            }
            html += '</ul>';
            const ins = s.insights || [];
            if (ins.length) {
                html += '<h4>' + esc(t('done_insights')) + '</h4><ul class="insurance-sim-debrief-insights">';
                for (let j = 0; j < ins.length; j++) html += '<li>' + esc(ins[j]) + '</li>';
                html += '</ul>';
            }
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            const round = (results && results.round) || this.getRound(state.currentPeriod);
            if (round === 1) {
                if (results.lossRatio > 1.5) return window.mySimulation.t('hint_unraveling');
                if (results.enrolled < 200) return window.mySimulation.t('hint_collapse');
                if (results.lossRatio > 1.0) return window.mySimulation.t('hint_loss');
            } else if (round === 2) {
                if (results.coinsurance < 5) return window.mySimulation.t('hint_full_coverage');
                if (results.coinsurance > 70) return window.mySimulation.t('hint_high_copay');
            } else {
                if (!results.mandate) return window.mySimulation.t('hint_no_mandate');
                if (results.coinsurance === 0) return window.mySimulation.t('hint_no_costshare');
            }
            return null;
        }

