        getPresets() { return null; }

        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            if (period > this.TOTAL_PERIODS) {
                this._finished = true;
                this._showRunComplete();
                return;
            }
            this._finished = false;
            this._hideRunComplete();
            const round = this.getRound(period);

            const titleEl = document.getElementById('roundTitle');
            const briefEl = document.getElementById('briefingText');
            if (titleEl) titleEl.innerHTML = window.mySimulation.t('round' + round + '_title');
            if (briefEl) briefEl.innerHTML = window.mySimulation.t('round' + round + '_brief');

            const r1 = document.getElementById('round1Controls');
            const r2 = document.getElementById('round2Controls');
            const r3 = document.getElementById('round3Controls');
            if (r1) r1.style.display = round === 1 ? 'block' : 'none';
            if (r2) r2.style.display = round === 2 ? 'block' : 'none';
            if (r3) r3.style.display = round === 3 ? 'block' : 'none';

            const badge = document.getElementById('roundBadge');
            if (badge) badge.innerHTML = window.mySimulation.t('round_badge_prefix') + ' ' + round + ' / 3';
        }

        _showRunComplete() {
            const t = this._t();
            ['round1Controls', 'round2Controls', 'round3Controls'].forEach(function(id) {
                const el = document.getElementById(id);
                if (el) el.style.display = 'none';
            });
            const row = document.getElementById('actionRow');
            if (row) row.style.display = 'none';
            const submit = document.getElementById('nextPeriodBtn');
            if (submit) submit.disabled = true;
            const titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = t('run_complete_title');
            const briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = t('run_complete_body');
            const badge = document.getElementById('roundBadge');
            if (badge) badge.innerHTML = t('run_complete_badge');
            const host = document.getElementById('completionPanel');
            if (host) {
                const sim = window.mySimulation;
                const summ = (sim && sim.lastSummary) ? sim.lastSummary
                           : (sim && sim.state ? this.getPerformanceSummary(sim.state.history || []) : null);
                if (summ) host.innerHTML = this.formatCompletionMessage(summ);
                host.style.display = 'block';
            }
        }

        _hideRunComplete() {
            const host = document.getElementById('completionPanel');
            if (host) host.style.display = 'none';
            const row = document.getElementById('actionRow');
            if (row) row.style.display = '';
        }

        _syncControlsFromDecisions(state) {
            const d = (state && state.decisions) || {};
            const vals = { premiumInput: d.premium, coinsuranceInput: d.coinsurance, costShareInput: d.cs_round3 };
            Object.keys(vals).forEach(function(id) {
                const el = document.getElementById(id);
                if (el && vals[id] != null) el.value = String(vals[id]);
            });
            const checks = { leverMandate: d.mandate, leverRiskRated: d.riskRated, leverManagedCare: d.managedCare };
            Object.keys(checks).forEach(function(id) {
                const el = document.getElementById(id);
                if (el) el.checked = !!checks[id];
            });
        }

